"""Send three Artifacts and three Crests to Kathleen using verified native GM mail.
Native class/level/stat rules are retained; no currency or inventory SQL edits.
"""
import base64
import hashlib
import os
from pathlib import Path
import subprocess
import sys
VM_UUID='7632fb78-37a0-f645-97c0-dc322c50b002'
FILES={'Item4.scp': 'ef57aaea1f793aecf388f1b209ac80ffb1ccd8e321f6eefcae79c3cdad92d009', 'Item3.scp': 'fd09784bc4a582c376a4befa5ef6a7c8f652e68294081da2bafb77559cfb7b80', 'Item.scp': 'b8b79a3caef7b48d56c1604d51c98be1497e63167916bb3a6f0286218eae6750', 'Item2.scp': '0c91422986344bd533be8edd701afb77e70b158a3cfbf39094f9fad0ca94c669'}
SQL=base64.b64decode('')
def decode_output(raw):
    if raw.startswith((b'\xff\xfe',b'\xfe\xff')):
        return raw.decode('utf-16',errors='replace')
    return raw.decode('utf-8-sig',errors='replace')
def main():
    if sys.argv[1:]!=['--apply']:
        raise SystemExit('EXPLICIT_APPLY_REQUIRED; NOTHING_SENT')
    if os.geteuid()!=0 or Path('/sys/class/dmi/id/product_uuid').read_text().strip().lower()!=VM_UUID:
        raise SystemExit('WRONG_TEST_VM_OR_ROOT_REQUIRED; NOTHING_SENT')
    for name,digest in FILES.items():
        p=subprocess.run(['docker','exec','cabal_main','cat','/etc/cabal/Data/'+name],capture_output=True,timeout=30)
        if p.returncode or hashlib.sha256(p.stdout).hexdigest()!=digest:
            raise SystemExit('ITEM_DEFINITION_CHANGED; FILE='+name+'; NOTHING_SENT')
    print('KATHLEEN_NATIVE_ITEM_DEFINITIONS_VERIFIED; SENDING_6_ATTACHMENTS_ONCE',flush=True)
    shell='''set +x
export SQLCMDPASSWORD="${MSSQL_SA_PASSWORD:-${SA_PASSWORD:-}}"
[ -n "$SQLCMDPASSWORD" ] || exit 2
tool=/opt/mssql-tools18/bin/sqlcmd
[ -x "$tool" ] || tool=/opt/mssql-tools/bin/sqlcmd
exec "$tool" -S localhost -U sa -N -C -d Server01 -b -l 5 -t 30 -h -1 -W -w 65535 -i /dev/stdin
'''
    p=subprocess.run(['docker','exec','-i','sql_main','sh','-ec',shell],input=SQL,capture_output=True,timeout=50)
    output=decode_output(p.stdout+p.stderr)
    # The fixed SQL returns ASCII labels, receipt markers and item/mail IDs only.
    # Definitions, account credentials and connection strings are never queried.
    for line in output.splitlines():
        if line.startswith(('KATHLEEN_','Msg ')) or any(x in line for x in ('NOTHING_SENT','MISMATCH','FAILED','DIFFERS','Invalid column','Invalid object')):
            print(line[:500],flush=True)
    if p.returncode or not any(mark in output for mark in ('KATHLEEN_ARTIFACTS_CRESTS_SENT;','KATHLEEN_ARTIFACTS_CRESTS_ALREADY_SENT;')):
        raise SystemExit('EQUIPMENT_DELIVERY_NOT_CONFIRMED; KEEP_OUTPUT; NO_CURRENCY_CHANGE')
    print('KATHLEEN_ARTIFACTS_CRESTS_TRANSACTION_CONFIRMED; OPEN_MAIL_AND_CLAIM; NO_CURRENCY_CHANGE',flush=True)
if __name__=='__main__':main()
